// Generated by scripts/reuse-run-policy.mjs from src/. Only host imports/types change.
export function approvalPrompt(tools: readonly { name: string; needsApproval?: boolean; judged?: boolean }[]) {
 const config = { tools };
 return [...config.tools.some(tool => tool.needsApproval) ? [`- The user approves each call of these tools before it runs, which pauses your turn until they answer: ${config.tools.filter(tool => tool.needsApproval).map(tool => tool.name).sort().join(", ")}.`] : [],
...config.tools.some(tool => tool.judged) ? [`- Each call of these tools is checked before it runs: an ordinary call runs, a risky one is refused (its result says so), and one that may be irreversible, or that the check is unsure about, pauses your turn for the user: ${config.tools.filter(tool => tool.judged).map(tool => tool.name).sort().join(", ")}.`] : [],];
}
